235	    std::vector<char> Serialize()
236	    {
237	        BinaryStream binaryStream;
238	        binaryStream << userRank;
239	        binaryStream << userRankSize;
240	        binaryStream << serverIdx;
241	        binaryStream << superPodIdx;
242	        binaryStream << deviceType;
243	        binaryStream << deviceNumPerModule;
244	        binaryStream << serverNumPerSuperPod;
245	        binaryStream << serverNum;
246	        binaryStream << moduleNum;
247	        binaryStream << superPodNum;
248	        binaryStream << moduleIdx;
249	        binaryStream << isDiffDeviceModule;
250	        binaryStream << multiModuleDiffDeviceNumMode;
251	        binaryStream << multiSuperPodDiffServerNumMode;
252	        binaryStream << isHCCSSWNumEqualToTwiceSIONum;
253	        binaryStream << mainThread;
254	        binaryStream << notifyNumOnMainThread;
255	        binaryStream << topoLevelNums;
256	        binaryStream << level0Topo;
257	        binaryStream << Level0Nhr;
258	        binaryStream << Level1Nhr;
259	        binaryStream << Level1Hd;
260	        binaryStream << is2DieFullMesh;
261	        binaryStream << level0PcieMix;
262	        binaryStream << level0BigClosRange;
263	        binaryStream << level2Uboe;
264	        binaryStream << level2Ubg;
265	        binaryStream << hostDpuOnly;
266	        binaryStream << level0Symmetric;
267	        binaryStream << level1Symmetric;
268	        binaryStream << topoInstDetailsOfLayerSize;
269	        binaryStream << level0MeshType;
270	        binaryStream << netLayerDetails.netLayerNum;
271	        binaryStream << netLayerDetails.netLayers;
272	        binaryStream << netLayerDetails.netInstNumOfLayer;
273	        binaryStream << netLayerDetails.instSizeListOfLayer;
274	        binaryStream << netLayerDetails.localNetInsSizeOfLayer;
275	        for (uint32_t idx = 0; idx < topoInstDetailsOfLayerSize; idx++) {
276	            binaryStream << topoInstDetailsOfLayer[idx].topoInstNum;
277	            binaryStream << topoInstDetailsOfLayer[idx].sizeOfTopo;
278	            binaryStream << topoInstDetailsOfLayer[idx].typeOfTopo;
279	            binaryStream << topoInstDetailsOfLayer[idx].ranksInTopo;
280	            binaryStream << topoInstDetailsOfLayer[idx].rankNumForTopoType;
281	        }
282	        std::vector<char> result;
283	        binaryStream.Dump(result);
284	        return result;
285	    }
286	
287	    void DeSerialize(std::vector<char>& data)
288	    {
289	        BinaryStream binaryStream(data);
290	        binaryStream >> userRank;
291	        binaryStream >> userRankSize;
292	        binaryStream >> serverIdx;
293	        binaryStream >> superPodIdx;
294	        binaryStream >> deviceType;
295	        binaryStream >> deviceNumPerModule;
296	        binaryStream >> serverNumPerSuperPod;
297	        binaryStream >> serverNum;
298	        binaryStream >> moduleNum;
299	        binaryStream >> superPodNum;
300	        binaryStream >> moduleIdx;
301	        binaryStream >> isDiffDeviceModule;
302	        binaryStream >> multiModuleDiffDeviceNumMode;
303	        binaryStream >> multiSuperPodDiffServerNumMode;
304	        binaryStream >> isHCCSSWNumEqualToTwiceSIONum;
305	        binaryStream >> mainThread;
306	        binaryStream >> notifyNumOnMainThread;
307	        binaryStream >> topoLevelNums;
308	        binaryStream >> level0Topo;
309	        binaryStream >> Level0Nhr;
310	        binaryStream >> Level1Nhr;
311	        binaryStream >> Level1Hd;
312	        binaryStream >> is2DieFullMesh;
313	        binaryStream >> level0PcieMix;
314	        binaryStream >> level0BigClosRange;
315	        binaryStream >> level2Uboe;
316	        binaryStream >> level2Ubg;
317	        binaryStream >> hostDpuOnly;
318	        binaryStream >> level0Symmetric;
319	        binaryStream >> level1Symmetric;
320	        binaryStream >> topoInstDetailsOfLayerSize;
321	        binaryStream >> level0MeshType;
322	        binaryStream >> netLayerDetails.netLayerNum;
323	        binaryStream >> netLayerDetails.netLayers;
324	        binaryStream >> netLayerDetails.netInstNumOfLayer;
325	        binaryStream >> netLayerDetails.instSizeListOfLayer;
326	        binaryStream >> netLayerDetails.localNetInsSizeOfLayer;
327	        if (topoInstDetailsOfLayerSize > HCCL_LOGIC_TOPO_LEVEL_NUM) {
328	            topoInstDetailsOfLayerSize = HCCL_LOGIC_TOPO_LEVEL_NUM;
329	        }
330	        topoInstDetailsOfLayer.resize(topoInstDetailsOfLayerSize);
331	        for (uint32_t idx = 0; idx < topoInstDetailsOfLayerSize; idx++) {
332	            binaryStream >> topoInstDetailsOfLayer[idx].topoInstNum;
333	            binaryStream >> topoInstDetailsOfLayer[idx].sizeOfTopo;
334	            binaryStream >> topoInstDetailsOfLayer[idx].typeOfTopo;
335	            binaryStream >> topoInstDetailsOfLayer[idx].ranksInTopo;
336	            binaryStream >> topoInstDetailsOfLayer[idx].rankNumForTopoType;
337	        }
338	    }
339	};
