381	// ccu快速下发上下文
382	struct CcuFastLaunchCtx {
383	    char algName[OP_ALG_LENGTH];
384	    u32 notifyNumOnMainThread = 0;
385	    u32 threadNum;
386	    u32 ccuKernelNum[MAX_TEMP_NUM_IN_ALGO]; // 每次调用template的KernelRun下发的kernel数量
387	    // 紧接ThreadHandle数组
388	    // 紧接CcuKernelSubmitInfo数组
389	
390	    ThreadHandle* GetThreadHandlePtr() const
391	    {
392	        size_t offset = offsetof(CcuFastLaunchCtx, ccuKernelNum) + sizeof(u32) * MAX_TEMP_NUM_IN_ALGO;
393	        return reinterpret_cast<ThreadHandle*>(reinterpret_cast<char*>(const_cast<CcuFastLaunchCtx*>(this)) + offset);
394	    }
395	    CcuKernelSubmitInfo* GetCcuKernelSubmitInfoPtr() const
396	    {
397	        size_t offset = offsetof(CcuFastLaunchCtx, ccuKernelNum) + sizeof(u32) * MAX_TEMP_NUM_IN_ALGO
398	                        + sizeof(ThreadHandle) * threadNum;
399	        return reinterpret_cast<CcuKernelSubmitInfo*>(
400	            reinterpret_cast<char*>(const_cast<CcuFastLaunchCtx*>(this)) + offset);
401	    }
402	
403	    static u64 GetCtxSize(u32 threadNum, u32 totalCcuKernelNum)
404	    {
405	        return sizeof(CcuFastLaunchCtx) + sizeof(ThreadHandle) * threadNum
406	               + sizeof(CcuKernelSubmitInfo) * totalCcuKernelNum;
407	    }
408	};
