503	        binaryStream << algHierarchyInfo.infos;
504	        binaryStream << cclMem;
505	        binaryStream << notifyNumOnMainThread;
506	        binaryStream << slaveThreadNum;
507	        binaryStream << waitTimeout;
508	        binaryStream << fullTimeout;
509	        binaryStream << notifyNumPerThread;
510	        binaryStream << commInfoPtr;
511	        binaryStream << threads;
512	        binaryStream << unfoldThread;
513	        binaryStream << channels;
514	        binaryStream << isHcommBatchTransferOnThreadSupported;
515	        binaryStream << isHcclThreadAcquireWithConfigSupported;
516	
517	        binaryStream << npu2DpuShmemPtr;
518	        binaryStream << dpu2NpuShmemPtr;
519	
520	        binaryStream << ccuKernelNum;
521	        binaryStream << ccuKernels;
522	        binaryStream << dieSplitRatio;
523	        std::vector<char> seq = topoInfo.Serialize();
524	        topoInfoSeqSize = seq.size();
525	        binaryStream << topoInfoSeqSize;
526	        std::vector<char> result;
527	        binaryStream.Dump(result);
528	        result.insert(result.end(), seq.begin(), seq.end());
529	
530	        return result;
531	    }
532	
533	    void DeSerialize(std::vector<char>& data)
534	    {
535	        BinaryStream binaryStream(data);
536	
537	        binaryStream >> algType;
538	        binaryStream >> algHierarchyInfo.infos;
539	        binaryStream >> cclMem;
540	        binaryStream >> notifyNumOnMainThread;
541	        binaryStream >> slaveThreadNum;
542	        binaryStream >> waitTimeout;
543	        binaryStream >> fullTimeout;
544	        binaryStream >> notifyNumPerThread;
545	        binaryStream >> commInfoPtr;
546	        binaryStream >> threads;
547	        binaryStream >> unfoldThread;
548	        binaryStream >> channels;
549	        binaryStream >> isHcommBatchTransferOnThreadSupported;
550	        binaryStream >> isHcclThreadAcquireWithConfigSupported;
551	
552	        binaryStream >> npu2DpuShmemPtr;
553	        binaryStream >> dpu2NpuShmemPtr;
554	
555	        binaryStream >> ccuKernelNum;
556	        binaryStream >> ccuKernels;
557	        binaryStream >> dieSplitRatio;
558	        binaryStream >> topoInfoSeqSize;
559	        size_t startPos = data.size() - topoInfoSeqSize;
560	        std::vector<char> tailData(data.begin() + startPos, data.end());
561	        TopoInfoWithNetLayerDetails topoTemp;
562	        topoTemp.DeSerialize(tailData);
563	        topoInfo = std::move(topoTemp);
564	    }
